"use client";

import { useEffect, useState } from "react";
import { fetchApi } from "@/lib/api";
import {
  Users,
  CircleDot,
  CreditCard,
  ShieldAlert,
  Wallet,
  TrendingUp,
  Loader2,
  RefreshCw,
} from "lucide-react";

interface DashboardStats {
  totalUsers: number;
  activeCircles: number;
  totalPayments: number;
  pendingKyc: number;
  totalVolume: number;
}

export default function AdminDashboardPage() {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchStats = async (isRefresh = false) => {
    if (isRefresh) {
      setLoading(true);
      setError(null);
    }
    try {
      const data = await fetchApi("/admin/dashboard");
      setStats(data);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Erreur lors du chargement");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const init = async () => {
      try {
        const data = await fetchApi("/admin/dashboard");
        setStats(data);
      } catch (err: unknown) {
        setError(err instanceof Error ? err.message : "Erreur lors du chargement");
      } finally {
        setLoading(false);
      }
    };
    init();
  }, []);

  const cards = stats
    ? [
        {
          label: "Utilisateurs inscrits",
          value: stats.totalUsers.toLocaleString("fr-FR"),
          icon: Users,
          color: "bg-[#bae8e8]",
          trend: null,
        },
        {
          label: "Cercles actifs",
          value: stats.activeCircles.toLocaleString("fr-FR"),
          icon: CircleDot,
          color: "bg-[#ffd803]/20",
          trend: null,
        },
        {
          label: "Paiements enregistrés",
          value: stats.totalPayments.toLocaleString("fr-FR"),
          icon: CreditCard,
          color: "bg-[#e3f6f5]",
          trend: null,
        },
        {
          label: "KYC en attente",
          value: stats.pendingKyc.toLocaleString("fr-FR"),
          icon: ShieldAlert,
          color: stats.pendingKyc > 0 ? "bg-[#f25f4c]/10" : "bg-[#42c88f]/10",
          trend: stats.pendingKyc > 0 ? "warning" : "ok",
        },
        {
          label: "Volume total confirmé",
          value: `${stats.totalVolume.toLocaleString("fr-FR")} FCFA`,
          icon: Wallet,
          color: "bg-[#272343]/5",
          trend: null,
        },
      ]
    : [];

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-4xl font-black text-[#272343] tracking-tight">
            Dashboard <span className="text-[#ffd803]">Global</span>
          </h1>
          <p className="text-[#2d334a]/60 font-medium mt-1">
            Vue d&apos;ensemble de la plateforme TontinePro.
          </p>
        </div>
        <button
          onClick={() => fetchStats(true)}
          disabled={loading}
          className="flex items-center gap-2 px-5 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-bold text-sm text-[#272343] hover:bg-[#e3f6f5] transition-all disabled:opacity-50"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          Actualiser
        </button>
      </div>

      {error && (
        <div className="p-4 bg-[#f25f4c]/10 border border-[#f25f4c]/20 text-[#f25f4c] rounded-2xl font-bold text-sm">
          {error}
        </div>
      )}

      {/* Stats Grid */}
      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="card-base h-32 animate-pulse bg-[#f8fafc] border-[#f0f0f0]" />
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {cards.map((card, i) => (
            <div
              key={i}
              className="card-base flex items-center gap-5 group hover:border-[#ffd803] transition-all"
            >
              <div
                className={`p-4 ${card.color} rounded-2xl group-hover:scale-110 transition-transform shrink-0`}
              >
                <card.icon
                  className={`h-6 w-6 ${
                    card.trend === "warning" ? "text-[#f25f4c]" : "text-[#272343]"
                  }`}
                />
              </div>
              <div>
                <p className="text-[10px] uppercase font-black tracking-widest text-[#2d334a]/40">
                  {card.label}
                </p>
                <p
                  className={`text-2xl font-black mt-0.5 ${
                    card.trend === "warning" ? "text-[#f25f4c]" : "text-[#272343]"
                  }`}
                >
                  {card.value}
                </p>
                {card.trend === "warning" && (
                  <p className="text-[10px] text-[#f25f4c] font-bold mt-0.5">
                    Action requise
                  </p>
                )}
                {card.trend === "ok" && (
                  <p className="text-[10px] text-[#42c88f] font-bold mt-0.5">
                    Tout est à jour
                  </p>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Indicateurs de santé */}
      <div className="card-base">
        <h2 className="text-xl font-black text-[#272343] mb-6 flex items-center gap-2">
          <TrendingUp className="h-5 w-5 text-[#ffd803]" />
          Indicateurs de santé
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* KYC */}
          <div className="p-5 bg-[#f8fafc] rounded-2xl border border-[#dfe5f2]">
            <div className="flex items-center justify-between mb-3">
              <p className="text-xs font-black uppercase tracking-widest text-[#2d334a]/40">
                KYC
              </p>
              <span
                className={`text-[10px] font-black px-2 py-0.5 rounded-full ${
                  (stats?.pendingKyc ?? 0) > 0
                    ? "bg-[#f25f4c]/10 text-[#f25f4c]"
                    : "bg-[#42c88f]/10 text-[#42c88f]"
                }`}
              >
                {(stats?.pendingKyc ?? 0) > 0 ? "En attente" : "OK"}
              </span>
            </div>
            <p className="text-3xl font-black text-[#272343]">
              {loading ? "—" : stats?.pendingKyc}
            </p>
            <p className="text-xs text-[#2d334a]/60 font-medium mt-1">
              demandes à traiter
            </p>
          </div>

          {/* Cercles */}
          <div className="p-5 bg-[#f8fafc] rounded-2xl border border-[#dfe5f2]">
            <div className="flex items-center justify-between mb-3">
              <p className="text-xs font-black uppercase tracking-widest text-[#2d334a]/40">
                Cercles
              </p>
              <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-[#42c88f]/10 text-[#42c88f]">
                Actifs
              </span>
            </div>
            <p className="text-3xl font-black text-[#272343]">
              {loading ? "—" : stats?.activeCircles}
            </p>
            <p className="text-xs text-[#2d334a]/60 font-medium mt-1">
              cercles en cours
            </p>
          </div>

          {/* Volume */}
          <div className="p-5 bg-[#272343] rounded-2xl">
            <div className="flex items-center justify-between mb-3">
              <p className="text-xs font-black uppercase tracking-widest text-white/40">
                Volume
              </p>
              <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-[#ffd803]/20 text-[#ffd803]">
                Confirmé
              </span>
            </div>
            <p className="text-2xl font-black text-white">
              {loading ? "—" : `${(stats?.totalVolume ?? 0).toLocaleString("fr-FR")}`}
            </p>
            <p className="text-xs text-white/40 font-medium mt-1">FCFA gérés</p>
          </div>
        </div>
      </div>

      {/* Raccourcis */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {[
          {
            href: "/admin/kyc",
            label: "Gérer les KYC",
            desc: "Approuver ou rejeter les demandes",
            color: "border-[#ffd803] hover:bg-[#ffd803]/5",
          },
          {
            href: "/admin/users",
            label: "Gérer les utilisateurs",
            desc: "Voir, bannir ou débannir",
            color: "border-[#bae8e8] hover:bg-[#bae8e8]/20",
          },
          {
            href: "/admin/settings",
            label: "Paramètres plateforme",
            desc: "Configurer les frais de service",
            color: "border-[#dfe5f2] hover:bg-[#f8fafc]",
          },
        ].map((item) => (
          <a
            key={item.href}
            href={item.href}
            className={`card-base border-2 ${item.color} transition-all group`}
          >
            <p className="font-black text-[#272343] group-hover:text-[#272343]">
              {item.label}
            </p>
            <p className="text-sm text-[#2d334a]/60 font-medium mt-1">{item.desc}</p>
          </a>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { fetchApi } from "@/lib/api";
import {
  AlertTriangle, Clock, CheckCircle2, RefreshCw, Loader2, Filter, X,
} from "lucide-react";

type DisputeStatus = "OPEN" | "IN_REVIEW" | "RESOLVED" | "CLOSED";

interface Dispute {
  id: string;
  subject: string;
  description: string;
  status: DisputeStatus;
  resolution: string | null;
  createdAt: string;
  circle: { id: string; name: string };
  reporter: { id: string; name: string; email: string };
}

const STATUS_CONFIG: Record<DisputeStatus, { label: string; color: string; icon: React.ElementType }> = {
  OPEN:      { label: "Ouvert",    color: "bg-[#f25f4c]/10 text-[#f25f4c]",  icon: AlertTriangle },
  IN_REVIEW: { label: "En cours",  color: "bg-[#ffd803]/10 text-[#b38a00]",  icon: Clock },
  RESOLVED:  { label: "Résolu",    color: "bg-[#42c88f]/10 text-[#42c88f]",  icon: CheckCircle2 },
  CLOSED:    { label: "Clôturé",   color: "bg-[#dfe5f2] text-[#2d334a]/60",  icon: CheckCircle2 },
};

import { useToast } from "@/lib/toast";

export default function AdminDisputesPage() {
  const { success, error: toastError } = useToast();
  const [disputes, setDisputes] = useState<Dispute[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<DisputeStatus | "ALL">("OPEN");
  const [selected, setSelected] = useState<Dispute | null>(null);
  const [resolution, setResolution] = useState("");
  const [newStatus, setNewStatus] = useState<DisputeStatus>("RESOLVED");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchDisputes = async () => {
    setLoading(true);
    setError(null);
    try {
      const params = filter !== "ALL" ? `?status=${filter}` : "";
      const data = await fetchApi(`/disputes${params}`);
      setDisputes(data.disputes);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchDisputes(); }, [filter]);

  const handleResolve = async () => {
    if (!selected) return;
    setSaving(true);
    try {
      await fetchApi(`/disputes/${selected.id}`, {
        method: "PATCH",
        body: JSON.stringify({ status: newStatus, resolution: resolution || undefined }),
      });
      setSelected(null);
      setResolution("");
      fetchDisputes();
      success("Litige mis à jour");
    } catch (e: any) {
      toastError(e.message);
    } finally {
      setSaving(false);
    }
  };

  const filters: { label: string; value: DisputeStatus | "ALL" }[] = [
    { label: "Ouverts", value: "OPEN" },
    { label: "En cours", value: "IN_REVIEW" },
    { label: "Résolus", value: "RESOLVED" },
    { label: "Tous", value: "ALL" },
  ];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-4xl font-black text-[#272343] tracking-tight">
            Gestion <span className="text-[#ffd803]">Litiges</span>
          </h1>
          <p className="text-[#2d334a]/60 font-medium mt-1">
            Traitez les signalements des membres.
          </p>
        </div>
        <button onClick={fetchDisputes} disabled={loading}
          className="flex items-center gap-2 px-5 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-bold text-sm text-[#272343] hover:bg-[#e3f6f5] transition-all disabled:opacity-50">
          <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          Actualiser
        </button>
      </div>

      {/* Filtres */}
      <div className="flex items-center gap-2 flex-wrap">
        <Filter className="h-4 w-4 text-[#2d334a]/40" />
        {filters.map((f) => (
          <button key={f.value} onClick={() => setFilter(f.value)}
            className={`px-4 py-2 rounded-xl text-sm font-black transition-all ${
              filter === f.value ? "bg-[#272343] text-[#ffd803]" : "bg-[#f8fafc] text-[#2d334a]/60 border border-[#dfe5f2] hover:border-[#272343]"
            }`}>
            {f.label}
            {f.value !== "ALL" && (
              <span className="ml-1.5 opacity-60">
                {disputes.filter((d) => d.status === f.value).length}
              </span>
            )}
          </button>
        ))}
      </div>

      {error && <p className="text-sm text-[#f25f4c] font-bold">{error}</p>}

      {/* Liste */}
      {loading ? (
        <div className="space-y-3">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="card-base h-24 animate-pulse bg-[#f8fafc] border-[#f0f0f0]" />
          ))}
        </div>
      ) : disputes.length === 0 ? (
        <div className="card-base text-center py-20">
          <CheckCircle2 className="h-12 w-12 text-[#42c88f] mx-auto mb-4" />
          <p className="font-black text-[#272343] text-lg">Aucun litige</p>
          <p className="text-[#2d334a]/60 font-medium mt-1">Aucun signalement dans cette catégorie.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {disputes.map((d) => {
            const cfg = STATUS_CONFIG[d.status];
            const Icon = cfg.icon;
            return (
              <div key={d.id}
                className="card-base hover:border-[#ffd803] transition-all cursor-pointer"
                onClick={() => { setSelected(d); setNewStatus(d.status === "OPEN" ? "IN_REVIEW" : "RESOLVED"); }}>
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div className="flex items-start gap-4">
                    <div className="w-10 h-10 bg-[#e3f6f5] rounded-2xl flex items-center justify-center shrink-0">
                      <AlertTriangle className="h-5 w-5 text-[#272343]" />
                    </div>
                    <div>
                      <p className="font-black text-[#272343]">{d.subject}</p>
                      <p className="text-sm text-[#2d334a]/60 font-medium mt-0.5 line-clamp-1">{d.description}</p>
                      <div className="flex items-center gap-3 mt-1">
                        <span className="text-[10px] font-bold text-[#2d334a]/40 uppercase tracking-widest">
                          {d.circle.name}
                        </span>
                        <span className="text-[10px] text-[#2d334a]/40">·</span>
                        <span className="text-[10px] font-bold text-[#2d334a]/40">
                          {d.reporter.name}
                        </span>
                        <span className="text-[10px] text-[#2d334a]/40">·</span>
                        <span className="text-[10px] text-[#2d334a]/40">
                          {new Date(d.createdAt).toLocaleDateString("fr-FR")}
                        </span>
                      </div>
                    </div>
                  </div>
                  <span className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-black shrink-0 ${cfg.color}`}>
                    <Icon className="h-3.5 w-3.5" />
                    {cfg.label}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal traitement */}
      {selected && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[32px] p-8 w-full max-w-lg shadow-2xl animate-in fade-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-[#272343]">Traiter le litige</h3>
              <button onClick={() => setSelected(null)} className="p-2 hover:bg-[#f8fafc] rounded-xl transition-all">
                <X className="h-5 w-5 text-[#2d334a]/60" />
              </button>
            </div>

            <div className="p-4 bg-[#f8fafc] rounded-2xl border border-[#dfe5f2] mb-6">
              <p className="font-black text-[#272343] text-sm">{selected.subject}</p>
              <p className="text-xs text-[#2d334a]/60 font-medium mt-1">{selected.description}</p>
              <p className="text-[10px] text-[#2d334a]/40 font-bold uppercase tracking-widest mt-2">
                {selected.reporter.name} · {selected.circle.name}
              </p>
            </div>

            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-[#2d334a]/40">Nouveau statut</label>
                <select value={newStatus} onChange={(e) => setNewStatus(e.target.value as DisputeStatus)}
                  className="input-base">
                  <option value="IN_REVIEW">En cours d'examen</option>
                  <option value="RESOLVED">Résolu</option>
                  <option value="CLOSED">Clôturé</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-[#2d334a]/40">
                  Résolution / Note (optionnel)
                </label>
                <textarea value={resolution} onChange={(e) => setResolution(e.target.value)}
                  placeholder="Expliquez la décision prise…"
                  rows={3}
                  className="input-base resize-none" />
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button onClick={() => setSelected(null)}
                className="flex-1 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-black text-[#272343] hover:bg-[#e3f6f5] transition-all">
                Annuler
              </button>
              <button onClick={handleResolve} disabled={saving}
                className="flex-1 py-3 bg-[#272343] text-[#ffd803] rounded-xl font-black transition-all disabled:opacity-50 flex items-center justify-center gap-2">
                {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                Confirmer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { fetchApi } from "@/lib/api";
import { useToast } from "@/lib/toast";
import {
  ShieldCheck, ShieldX, Clock, ExternalLink,
  Loader2, RefreshCw, Search, X, Bot, Eye,
} from "lucide-react";

type KycStatus = "PENDING" | "APPROVED" | "REJECTED";

interface KycRequest {
  id: string;
  documentUrl: string;
  status: KycStatus;
  reviewedAt: string | null;
  reviewNote: string | null;
  ocrConfidence: number | null;
  ocrAutoApproved: boolean;
  createdAt: string;
  user: { id: string; name: string; email: string };
}

const STATUS_CONFIG: Record<KycStatus, { label: string; color: string; icon: React.ElementType }> = {
  PENDING:  { label: "En attente", color: "bg-[#ffd803]/10 text-[#b38a00]",  icon: Clock },
  APPROVED: { label: "Approuvé",   color: "bg-[#42c88f]/10 text-[#42c88f]",  icon: ShieldCheck },
  REJECTED: { label: "Rejeté",     color: "bg-[#f25f4c]/10 text-[#f25f4c]",  icon: ShieldX },
};

export default function AdminKycPage() {
  const { success, error: toastError } = useToast();
  const [requests, setRequests] = useState<KycRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<KycStatus | "ALL">("ALL");
  const [search, setSearch] = useState("");
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [noteModal, setNoteModal] = useState<{ id: string; action: "approve" | "reject" } | null>(null);
  const [note, setNote] = useState("");
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fetchRequests = async () => {
    setLoading(true);
    setError(null);
    try {
      // Toujours charger tous les KYC — le filtre se fait côté client
      const data = await fetchApi("/admin/kyc");
      setRequests(data.requests);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchRequests(); }, []);

  // Filtrage combiné : statut + recherche
  const filtered = useMemo(() => {
    return requests.filter((r) => {
      const matchStatus = statusFilter === "ALL" || r.status === statusFilter;
      const q = search.toLowerCase();
      const matchSearch =
        !q ||
        r.user.name.toLowerCase().includes(q) ||
        r.user.email.toLowerCase().includes(q);
      return matchStatus && matchSearch;
    });
  }, [requests, statusFilter, search]);

  // Compteurs par statut
  const counts = useMemo(() => ({
    ALL:      requests.length,
    PENDING:  requests.filter((r) => r.status === "PENDING").length,
    APPROVED: requests.filter((r) => r.status === "APPROVED").length,
    REJECTED: requests.filter((r) => r.status === "REJECTED").length,
  }), [requests]);

  const handleReview = async () => {
    if (!noteModal) return;
    setActionLoading(noteModal.id);
    try {
      await fetchApi(`/admin/kyc/${noteModal.id}`, {
        method: "PATCH",
        body: JSON.stringify({ action: noteModal.action, note }),
      });
      setNoteModal(null);
      setNote("");
      fetchRequests();
      success(noteModal.action === "approve" ? "KYC approuvé" : "KYC rejeté");
    } catch (err: any) {
      toastError(err.message);
    } finally {
      setActionLoading(null);
    }
  };

  const isImage = (url: string) => /\.(jpg|jpeg|png|webp)$/i.test(url);

  const statusTabs: { label: string; value: KycStatus | "ALL" }[] = [
    { label: "Tous",        value: "ALL" },
    { label: "En attente",  value: "PENDING" },
    { label: "Approuvés",   value: "APPROVED" },
    { label: "Rejetés",     value: "REJECTED" },
  ];

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-4xl font-black text-[#272343] tracking-tight">
            Validation <span className="text-[#ffd803]">KYC</span>
          </h1>
          <p className="text-[#2d334a]/60 font-medium mt-1">
            {requests.length} demande{requests.length !== 1 ? "s" : ""} au total
          </p>
        </div>
        <button onClick={fetchRequests} disabled={loading}
          className="flex items-center gap-2 px-5 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-bold text-sm text-[#272343] hover:bg-[#e3f6f5] transition-all disabled:opacity-50">
          <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          Actualiser
        </button>
      </div>

      {/* Barre de recherche + onglets statut */}
      <div className="space-y-3">
        {/* Recherche */}
        <div className="relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-[#2d334a]/30" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Rechercher par nom ou email…"
            className="w-full h-11 pl-11 pr-10 bg-white border border-[#dfe5f2] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#ffd803] transition-all placeholder:text-[#2d334a]/30"
          />
          {search && (
            <button onClick={() => setSearch("")}
              className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-[#2d334a]/30 hover:text-[#272343]">
              <X className="h-4 w-4" />
            </button>
          )}
        </div>

        {/* Onglets statut */}
        <div className="flex items-center gap-2 flex-wrap">
          {statusTabs.map((t) => (
            <button key={t.value} onClick={() => setStatusFilter(t.value)}
              className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-sm font-black transition-all ${
                statusFilter === t.value
                  ? "bg-[#272343] text-[#ffd803]"
                  : "bg-[#f8fafc] text-[#2d334a]/60 border border-[#dfe5f2] hover:border-[#272343]"
              }`}>
              {t.label}
              <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-black ${
                statusFilter === t.value ? "bg-[#ffd803]/20 text-[#ffd803]" : "bg-[#dfe5f2] text-[#2d334a]/60"
              }`}>
                {counts[t.value]}
              </span>
            </button>
          ))}
          {(search || statusFilter !== "ALL") && (
            <span className="text-xs text-[#2d334a]/40 font-medium ml-1">
              {filtered.length} résultat{filtered.length !== 1 ? "s" : ""}
            </span>
          )}
        </div>
      </div>

      {error && <p className="text-sm text-[#f25f4c] font-bold">{error}</p>}

      {/* Tableau */}
      {loading ? (
        <div className="flex justify-center py-16">
          <Loader2 className="h-8 w-8 animate-spin text-[#ffd803]" />
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-20 border-2 border-dashed border-[#dfe5f2] rounded-2xl">
          <ShieldCheck className="h-10 w-10 text-[#2d334a]/20 mx-auto mb-3" />
          <p className="font-black text-[#272343]">Aucune demande</p>
          <p className="text-sm text-[#2d334a]/40 font-medium mt-1">
            {search ? "Aucun résultat pour cette recherche." : "Aucune demande KYC dans cette catégorie."}
          </p>
        </div>
      ) : (
        <div className="bg-white border border-[#dfe5f2] rounded-2xl overflow-hidden">
          {/* En-tête tableau */}
          <div className="hidden md:grid grid-cols-[2fr_2fr_1fr_1fr_1fr_auto] gap-4 px-5 py-3 bg-[#f8fafc] border-b border-[#dfe5f2] text-[10px] font-black uppercase tracking-widest text-[#2d334a]/40">
            <span>Utilisateur</span>
            <span>Note / OCR</span>
            <span>Statut</span>
            <span>Date</span>
            <span>Document</span>
            <span>Actions</span>
          </div>

          {/* Lignes */}
          <div className="divide-y divide-[#dfe5f2]">
            {filtered.map((req) => {
              const cfg = STATUS_CONFIG[req.status];
              const StatusIcon = cfg.icon;
              const isLocalImg = req.documentUrl.includes("/uploads/kyc/") && isImage(req.documentUrl);

              return (
                <div key={req.id}
                  className="grid grid-cols-1 md:grid-cols-[2fr_2fr_1fr_1fr_1fr_auto] gap-4 px-5 py-4 hover:bg-[#f8fafc] transition-colors items-center">

                  {/* Utilisateur */}
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 bg-[#e3f6f5] rounded-xl flex items-center justify-center font-black text-[#272343] text-sm shrink-0">
                      {req.user.name.charAt(0).toUpperCase()}
                    </div>
                    <div className="min-w-0">
                      <p className="font-black text-sm text-[#272343] truncate">{req.user.name}</p>
                      <p className="text-xs text-[#2d334a]/40 font-medium truncate">{req.user.email}</p>
                    </div>
                  </div>

                  {/* Note / OCR */}
                  <div className="space-y-1">
                    <div className="flex items-center gap-1.5 flex-wrap">
                      {req.ocrAutoApproved && (
                        <span className="flex items-center gap-1 text-[9px] font-black px-2 py-0.5 rounded-md bg-[#42c88f]/10 text-[#42c88f]">
                          <Bot className="h-3 w-3" /> Auto
                        </span>
                      )}
                      {req.ocrConfidence !== null && req.ocrConfidence >= 0 && (
                        <span className={`text-[9px] font-black px-2 py-0.5 rounded-md ${
                          req.ocrConfidence >= 75 ? "bg-[#42c88f]/10 text-[#42c88f]"
                          : req.ocrConfidence >= 50 ? "bg-[#ffd803]/10 text-[#b38a00]"
                          : "bg-[#f25f4c]/10 text-[#f25f4c]"
                        }`}>
                          OCR {req.ocrConfidence}%
                        </span>
                      )}
                      {req.ocrConfidence === null && req.status === "PENDING" && (
                        <span className="text-[9px] font-black px-2 py-0.5 rounded-md bg-[#dfe5f2] text-[#2d334a]/60">
                          Analyse…
                        </span>
                      )}
                    </div>
                    {req.reviewNote && (
                      <p className="text-[10px] text-[#2d334a]/50 italic line-clamp-2">{req.reviewNote}</p>
                    )}
                  </div>

                  {/* Statut */}
                  <span className={`flex items-center gap-1 text-[10px] font-black px-2.5 py-1.5 rounded-lg w-fit ${cfg.color}`}>
                    <StatusIcon className="h-3 w-3" />
                    {cfg.label}
                  </span>

                  {/* Date */}
                  <p className="text-xs text-[#2d334a]/40 font-medium">
                    {new Date(req.createdAt).toLocaleDateString("fr-FR", {
                      day: "2-digit", month: "short", year: "numeric"
                    })}
                  </p>

                  {/* Document */}
                  <div className="flex items-center gap-2">
                    {isLocalImg ? (
                      <button onClick={() => setPreviewUrl(req.documentUrl)}
                        className="flex items-center gap-1 text-[10px] font-black px-2.5 py-1.5 bg-[#f8fafc] border border-[#dfe5f2] rounded-lg hover:bg-[#e3f6f5] transition-all">
                        <Eye className="h-3 w-3" /> Aperçu
                      </button>
                    ) : (
                      <a href={req.documentUrl} target="_blank" rel="noopener noreferrer"
                        className="flex items-center gap-1 text-[10px] font-black px-2.5 py-1.5 bg-[#f8fafc] border border-[#dfe5f2] rounded-lg hover:bg-[#e3f6f5] transition-all">
                        <ExternalLink className="h-3 w-3" /> Ouvrir
                      </a>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-2">
                    {req.status === "PENDING" ? (
                      <>
                        <button onClick={() => setNoteModal({ id: req.id, action: "approve" })}
                          disabled={actionLoading === req.id}
                          className="flex items-center gap-1 px-3 py-1.5 bg-[#42c88f] text-white text-[10px] font-black rounded-lg hover:bg-[#38b07d] transition-all disabled:opacity-50">
                          {actionLoading === req.id ? <Loader2 className="h-3 w-3 animate-spin" /> : <ShieldCheck className="h-3 w-3" />}
                          OK
                        </button>
                        <button onClick={() => setNoteModal({ id: req.id, action: "reject" })}
                          disabled={actionLoading === req.id}
                          className="flex items-center gap-1 px-3 py-1.5 bg-[#f25f4c] text-white text-[10px] font-black rounded-lg hover:bg-[#d94f3d] transition-all disabled:opacity-50">
                          <ShieldX className="h-3 w-3" /> ✕
                        </button>
                      </>
                    ) : (
                      <span className="text-[10px] text-[#2d334a]/30 font-medium">—</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Modal aperçu image */}
      {previewUrl && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4"
          onClick={() => setPreviewUrl(null)}>
          <div className="relative max-w-2xl w-full" onClick={(e) => e.stopPropagation()}>
            <button onClick={() => setPreviewUrl(null)}
              className="absolute -top-10 right-0 text-white/60 hover:text-white font-black text-sm flex items-center gap-1">
              <X className="h-5 w-5" /> Fermer
            </button>
            <img src={previewUrl} alt="Document KYC" className="w-full rounded-2xl shadow-2xl" />
          </div>
        </div>
      )}

      {/* Modal approbation / rejet */}
      {noteModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[32px] p-8 w-full max-w-md shadow-2xl animate-in fade-in zoom-in-95 duration-200">
            <h3 className="text-xl font-black text-[#272343] mb-2">
              {noteModal.action === "approve" ? "✅ Approuver la demande" : "❌ Rejeter la demande"}
            </h3>
            <p className="text-sm text-[#2d334a]/60 font-medium mb-6">
              {noteModal.action === "approve"
                ? "L'utilisateur sera promu au rôle Organisateur."
                : "Précisez la raison du rejet (optionnel)."}
            </p>
            <textarea value={note} onChange={(e) => setNote(e.target.value)}
              placeholder="Note optionnelle…" rows={3} className="input-base resize-none mb-6" />
            <div className="flex gap-3">
              <button onClick={() => { setNoteModal(null); setNote(""); }}
                className="flex-1 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-black text-[#272343] hover:bg-[#e3f6f5] transition-all">
                Annuler
              </button>
              <button onClick={handleReview} disabled={!!actionLoading}
                className={`flex-1 py-3 rounded-xl font-black text-white transition-all disabled:opacity-50 flex items-center justify-center gap-2 ${
                  noteModal.action === "approve" ? "bg-[#42c88f] hover:bg-[#38b07d]" : "bg-[#f25f4c] hover:bg-[#d94f3d]"
                }`}>
                {actionLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                Confirmer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { fetchApi } from "@/lib/api";
import {
  Settings,
  Save,
  Loader2,
  RefreshCw,
  Info,
  Percent,
  CreditCard,
} from "lucide-react";

interface SettingField {
  key: string;
  label: string;
  description: string;
  icon: React.ElementType;
  suffix?: string;
  type?: "number" | "text";
}

const SETTING_FIELDS: SettingField[] = [
  {
    key: "service_fee",
    label: "Frais de service",
    description: "Pourcentage prélevé sur chaque cycle de tontine.",
    icon: Percent,
    suffix: "%",
    type: "number",
  },
  {
    key: "transaction_fee",
    label: "Frais de transaction",
    description: "Frais fixes appliqués à chaque paiement Mobile Money.",
    icon: CreditCard,
    suffix: "FCFA",
    type: "number",
  },
];

export default function AdminSettingsPage() {
  const [settings, setSettings] = useState<Record<string, string>>({});
  const [form, setForm] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState<string | null>(null);
  const [saved, setSaved] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const fetchSettings = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchApi("/admin/settings");
      setSettings(data.settings);
      setForm(data.settings);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSettings();
  }, []);

  const handleSave = async (key: string) => {
    setSaving(key);
    setError(null);
    try {
      await fetchApi("/admin/settings", {
        method: "PATCH",
        body: JSON.stringify({ key, value: form[key] }),
      });
      setSettings((prev) => ({ ...prev, [key]: form[key] }));
      setSaved(key);
      setTimeout(() => setSaved(null), 2000);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setSaving(null);
    }
  };

  const hasChanged = (key: string) => form[key] !== settings[key];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-4xl font-black text-[#272343] tracking-tight">
            Paramètres <span className="text-[#ffd803]">Plateforme</span>
          </h1>
          <p className="text-[#2d334a]/60 font-medium mt-1">
            Configurez les frais et règles globales de TontinePro.
          </p>
        </div>
        <button
          onClick={fetchSettings}
          disabled={loading}
          className="flex items-center gap-2 px-5 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-bold text-sm text-[#272343] hover:bg-[#e3f6f5] transition-all disabled:opacity-50"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          Actualiser
        </button>
      </div>

      {/* Info banner */}
      <div className="flex items-start gap-3 p-4 bg-[#bae8e8]/20 border border-[#bae8e8] rounded-2xl">
        <Info className="h-5 w-5 text-[#272343] shrink-0 mt-0.5" />
        <p className="text-sm text-[#272343] font-medium">
          Les modifications sont appliquées immédiatement. Les frais seront pris en compte lors des
          prochains cycles et paiements.
        </p>
      </div>

      {error && (
        <div className="p-4 bg-[#f25f4c]/10 border border-[#f25f4c]/20 text-[#f25f4c] rounded-2xl font-bold text-sm">
          {error}
        </div>
      )}

      {/* Champs de paramètres */}
      {loading ? (
        <div className="space-y-4">
          {[...Array(2)].map((_, i) => (
            <div key={i} className="card-base h-32 animate-pulse bg-[#f8fafc] border-[#f0f0f0]" />
          ))}
        </div>
      ) : (
        <div className="space-y-6">
          {SETTING_FIELDS.map((field) => {
            const FieldIcon = field.icon;
            const isSaving = saving === field.key;
            const isSaved = saved === field.key;
            const changed = hasChanged(field.key);

            return (
              <div key={field.key} className="card-base hover:border-[#ffd803] transition-all">
                <div className="flex items-start gap-4 mb-6">
                  <div className="p-3 bg-[#ffd803]/10 rounded-2xl shrink-0">
                    <FieldIcon className="h-5 w-5 text-[#272343]" />
                  </div>
                  <div>
                    <p className="font-black text-[#272343]">{field.label}</p>
                    <p className="text-sm text-[#2d334a]/60 font-medium mt-0.5">
                      {field.description}
                    </p>
                    <p className="text-[10px] font-black uppercase tracking-widest text-[#2d334a]/30 mt-1">
                      Clé : {field.key}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  <div className="relative flex-1 max-w-xs">
                    <input
                      type={field.type ?? "text"}
                      value={form[field.key] ?? ""}
                      onChange={(e) =>
                        setForm((prev) => ({ ...prev, [field.key]: e.target.value }))
                      }
                      className="input-base pr-16"
                      placeholder="0"
                      step={field.type === "number" ? "0.01" : undefined}
                      min={field.type === "number" ? "0" : undefined}
                    />
                    {field.suffix && (
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-sm font-black text-[#2d334a]/40">
                        {field.suffix}
                      </span>
                    )}
                  </div>

                  <button
                    onClick={() => handleSave(field.key)}
                    disabled={isSaving || !changed}
                    className={`flex items-center gap-2 px-5 py-4 rounded-xl font-black text-sm transition-all disabled:opacity-40 ${
                      isSaved
                        ? "bg-[#42c88f] text-white"
                        : "bg-[#272343] text-[#ffd803] hover:bg-[#1a1730]"
                    }`}
                  >
                    {isSaving ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : isSaved ? (
                      <>✓ Sauvegardé</>
                    ) : (
                      <>
                        <Save className="h-4 w-4" />
                        Sauvegarder
                      </>
                    )}
                  </button>
                </div>

                {/* Valeur actuelle */}
                {settings[field.key] !== undefined && (
                  <p className="text-xs text-[#2d334a]/40 font-medium mt-3">
                    Valeur actuelle :{" "}
                    <span className="font-black text-[#272343]">
                      {settings[field.key]} {field.suffix}
                    </span>
                  </p>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Paramètres bruts */}
      {!loading && Object.keys(settings).length > 0 && (
        <div className="card-base">
          <h2 className="text-lg font-black text-[#272343] mb-4 flex items-center gap-2">
            <Settings className="h-5 w-5 text-[#ffd803]" />
            Tous les paramètres
          </h2>
          <div className="space-y-2">
            {Object.entries(settings).map(([key, value]) => (
              <div
                key={key}
                className="flex items-center justify-between p-3 bg-[#f8fafc] rounded-xl border border-[#dfe5f2]"
              >
                <span className="text-xs font-black text-[#2d334a]/60 uppercase tracking-widest">
                  {key}
                </span>
                <span className="text-sm font-black text-[#272343]">{value}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { fetchApi } from "@/lib/api";
import {
  Users,
  ShieldCheck,
  ShieldOff,
  ShieldAlert,
  Loader2,
  RefreshCw,
  Search,
  Ban,
  CheckCircle,
} from "lucide-react";

type UserStatus = "ACTIVE" | "BANNED" | "SUSPENDED";
type UserRole = "SUPER_ADMIN" | "ORGANISATEUR" | "MEMBRE";

interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  status: UserStatus;
  createdAt: string;
  kycRequest: { status: string } | null;
}

const ROLE_CONFIG: Record<UserRole, { label: string; color: string }> = {
  SUPER_ADMIN: { label: "Super Admin", color: "bg-[#272343] text-[#ffd803]" },
  ORGANISATEUR: { label: "Organisateur", color: "bg-[#ffd803]/10 text-[#b38a00]" },
  MEMBRE: { label: "Membre", color: "bg-[#bae8e8]/30 text-[#272343]" },
};

const STATUS_CONFIG: Record<UserStatus, { label: string; color: string; icon: React.ElementType }> = {
  ACTIVE: { label: "Actif", color: "bg-[#42c88f]/10 text-[#42c88f]", icon: CheckCircle },
  BANNED: { label: "Banni", color: "bg-[#f25f4c]/10 text-[#f25f4c]", icon: Ban },
  SUSPENDED: { label: "Suspendu", color: "bg-[#ffd803]/10 text-[#b38a00]", icon: ShieldAlert },
};

import { useToast } from "@/lib/toast";

export default function AdminUsersPage() {
  const { success, error: toastError } = useToast();
  const [users, setUsers] = useState<User[]>([]);
  const [filteredUsers, setFilteredUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [error, setError] = useState<string | null>(null);

  const fetchUsers = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchApi("/admin/users");
      setUsers(data.users);
      setFilteredUsers(data.users);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  useEffect(() => {
    if (search.trim() === "") {
      setFilteredUsers(users);
    } else {
      const query = search.toLowerCase();
      setFilteredUsers(
        users.filter(
          (u) =>
            u.name.toLowerCase().includes(query) ||
            u.email.toLowerCase().includes(query)
        )
      );
    }
  }, [search, users]);

  const handleBan = async (userId: string) => {
    setActionLoading(userId);
    try {
      await fetchApi(`/admin/users/${userId}/ban`, { method: "PATCH" });
      success(`Utilisateur banni`);
      fetchUsers();
    } catch (err: any) {
      toastError(err.message);
    } finally {
      setActionLoading(null);
    }
  };

  const handleUnban = async (userId: string) => {
    setActionLoading(userId);
    try {
      await fetchApi(`/admin/users/${userId}/unban`, { method: "PATCH" });
      success(`Utilisateur débanni`);
      fetchUsers();
    } catch (err: any) {
      toastError(err.message);
    } finally {
      setActionLoading(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-4xl font-black text-[#272343] tracking-tight">
            Gestion <span className="text-[#ffd803]">Utilisateurs</span>
          </h1>
          <p className="text-[#2d334a]/60 font-medium mt-1">
            Consultez, bannissez ou débannissez les utilisateurs.
          </p>
        </div>
        <button
          onClick={fetchUsers}
          disabled={loading}
          className="flex items-center gap-2 px-5 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-bold text-sm text-[#272343] hover:bg-[#e3f6f5] transition-all disabled:opacity-50"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          Actualiser
        </button>
      </div>

      {/* Recherche */}
      <div className="relative">
