                      ) : (
                        <button
                          onClick={() => handleBan(user.id)}
                          disabled={actionLoading === user.id}
                          className="flex items-center gap-1.5 px-4 py-2 bg-[#f25f4c] text-white text-xs font-black rounded-xl hover:bg-[#d94f3d] transition-all disabled:opacity-50"
                        >
                          {actionLoading === user.id ? (
                            <Loader2 className="h-3.5 w-3.5 animate-spin" />
                          ) : (
                            <Ban className="h-3.5 w-3.5" />
                          )}
                          Bannir
                        </button>
                      )}
                    </>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { fetchApi } from "@/lib/api";
import Link from "next/link";
import {
  BarChart3,
  TrendingUp,
  Users,
  Wallet,
  Activity,
  Calendar,
} from "lucide-react";

interface AnalyticsResponse {
  // Format retourné par /api/organizer/analytics
  stats: {
    totalVolume: number;
    activeMembers: number;
    collectionRate: number | null;
    paymentsThisMonth: { confirmed: number; total: number };
  };
  cashflow: Array<{ month: string; total: number }>;
  nextPayout: {
    circleId: string;
    circleName: string;
    date: string;
    daysLeft: number;
  } | null;
  topMembers: Array<{ userId: string; name: string; paymentsCount: number }>;
  // Champs legacy (au cas où)
  volume?: number;
  activeMembers?: number;
  collectionRate?: number | null;
  paymentsThisMonth?: { confirmed: number; total: number };
}

export default function AnalyticsPage() {
  const [data, setData] = useState<AnalyticsResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;
    setLoading(true);
    setError(null);

    fetchApi("/organizer/analytics")
      .then((response: AnalyticsResponse) => {
        if (!isMounted) return;
        setData(response);
      })
      .catch((err: Error) => {
        if (!isMounted) return;
        setError(err.message || "Erreur lors du chargement des statistiques");
      })
      .finally(() => {
        if (!isMounted) return;
        setLoading(false);
      });

    return () => {
      isMounted = false;
    };
  }, []);

  const stats = [
    {
      label: "Volume Géré",
      value: loading ? "—" : `${(data?.stats?.totalVolume ?? data?.volume ?? 0).toLocaleString("fr-FR")} FCFA`,
      icon: Wallet,
      bg: "bg-[#ffd803]/20",
    },
    {
      label: "Membres Actifs",
      value: loading ? "—" : String(data?.stats?.activeMembers ?? data?.activeMembers ?? 0),
      icon: Users,
      bg: "bg-[#bae8e8]",
    },
    {
      label: "Taux de Recouvrement",
      value: loading
        ? "—"
        : (data?.stats?.collectionRate ?? data?.collectionRate) != null
          ? `${data?.stats?.collectionRate ?? data?.collectionRate}%`
          : "N/A",
      icon: TrendingUp,
      bg: "bg-[#e3f6f5]",
    },
    {
      label: "Paiements ce Mois",
      value: loading
        ? "—"
        : (() => {
            const p = data?.stats?.paymentsThisMonth ?? data?.paymentsThisMonth;
            return p ? `${p.confirmed}/${p.total}` : "0/0";
          })(),
      icon: Activity,
      bg: "bg-[#f25f4c]/10",
    },
  ];

  const cashflowMax = useMemo(() => {
    if (!data?.cashflow?.length) return 0;
    return Math.max(...data.cashflow.map((entry) => entry.total));
  }, [data]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div>
        <h1 className="text-4xl font-black text-[#272343] tracking-tight">
          Tableau de <span className="text-[#ffd803]">Bord</span>
        </h1>
        <p className="text-[#2d334a]/60 mt-2 font-medium italic">
          Suivez la santé financière de vos tontines et l'activité de vos membres.
        </p>
      </div>

      {error && (
        <div className="bg-[#f25f4c]/10 border border-[#f25f4c] text-[#f25f4c] px-4 py-3 rounded-2xl font-bold">
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, i) => (
          <div
            key={i}
            className="bg-white p-6 rounded-[24px] border border-[#dfe5f2] shadow-sm hover:shadow-md transition-all group"
          >
            <div className="flex justify-between items-start mb-4">
              <div className={`p-3 rounded-2xl ${stat.bg} group-hover:scale-110 transition-transform`}>
                <stat.icon size={22} className="text-[#272343]" />
              </div>
            </div>
            <p className="text-[#2d334a]/40 text-xs font-bold uppercase tracking-widest leading-none">
              {stat.label}
            </p>
            <h3 className="text-2xl font-black text-[#272343] mt-2 tracking-tight">
              {stat.value}
            </h3>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white rounded-[32px] p-8 border border-[#dfe5f2] shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <BarChart3 className="text-[#ffd803]" />
              <h2 className="text-xl font-black text-[#272343]">Flux de Trésorerie</h2>
            </div>
            <select className="bg-[#f8fafc] border border-[#dfe5f2] rounded-xl px-4 py-2 text-sm font-bold text-[#272343] outline-none active:scale-95 transition-all">
              <option>6 derniers mois</option>
              <option>Cette année</option>
            </select>
          </div>

          <div className="h-[300px] w-full bg-[#f8fafc] rounded-2xl border-2 border-dashed border-[#dfe5f2] p-6">
            {!data?.cashflow?.length ? (
              <div className="h-full flex flex-col items-center justify-center text-[#2d334a]/30">
                <BarChart3 size={48} className="mb-2 opacity-20" />
                <p className="font-bold uppercase tracking-widest text-[10px]">
                  {loading ? "Chargement des donnees..." : "Aucune donnee disponible"}
                </p>
              </div>
            ) : (
              <div className="h-full flex flex-col justify-end gap-3">
                {data.cashflow.map((entry) => {
                  const width = cashflowMax ? Math.round((entry.total / cashflowMax) * 100) : 0;
                  return (
                    <div key={entry.month} className="space-y-1">
                      <div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-widest text-[#2d334a]/40">
                        <span>{entry.month}</span>
                        <span>{entry.total.toLocaleString("fr-FR")} CFA</span>
                      </div>
                      <div className="h-2 rounded-full bg-white border border-[#dfe5f2] overflow-hidden">
                        <div
                          className="h-full bg-[#bae8e8]"
                          style={{ width: `${width}%` }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-[#272343] rounded-[32px] p-8 text-white relative overflow-hidden group">
            <div className="relative z-10">
              <h3 className="text-lg font-black mb-2">Prochain Versement</h3>
              {data?.nextPayout ? (
                <>
                  <p className="text-white/60 text-sm mb-6 uppercase tracking-wider font-bold">
                    Cercle: {data.nextPayout.circleName}
                  </p>
                  <div className="flex items-center gap-4 mb-4">
                    <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center text-[#ffd803]">
                      <Calendar size={20} />
                    </div>
                    <div>
                      <p className="text-2xl font-black italic">
                        {new Date(data.nextPayout.date).toLocaleDateString("fr-FR", {
                          day: "2-digit",
                          month: "long",
                        })}
                      </p>
                      <p className="text-xs text-[#ffd803] font-bold uppercase">
                        Dans {data.nextPayout.daysLeft} jours
                      </p>
                    </div>
                  </div>
                  <Link
                    href={`/dashboard/circles/${data.nextPayout.circleId}`}
                    className="w-full bg-[#ffd803] text-[#272343] py-4 rounded-2xl font-black text-sm hover:bg-white transition-all active:scale-95 shadow-lg shadow-[#ffd803]/10 text-center block"
                  >
                    Gérer le cercle
                  </Link>
                </>
              ) : (
                <p className="text-white/60 text-sm font-bold uppercase tracking-wider">
                  {loading ? "Chargement..." : "Aucun versement planifie"}
                </p>
              )}
            </div>
            <div className="absolute -bottom-4 -right-4 w-32 h-32 bg-[#ffd803] rounded-full blur-[60px] opacity-20 group-hover:opacity-40 transition-opacity"></div>
          </div>

          <div className="bg-white rounded-[32px] p-8 border border-[#dfe5f2] shadow-sm">
            <h3 className="text-[#272343] font-black mb-4">Membres Actifs</h3>
            {!data?.topMembers?.length ? (
              <p className="text-[#2d334a]/40 text-xs font-bold uppercase tracking-widest">
                {loading ? "Chargement..." : "Aucune activite recente"}
              </p>
            ) : (
              <div className="space-y-4">
                {data.topMembers.map((member, index) => (
                  <div key={member.userId} className="flex items-center justify-between group cursor-default">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-[#bae8e8] flex items-center justify-center font-black text-[#272343] text-sm">
                        {String.fromCharCode(65 + index)}
                      </div>
                      <div>
                        <p className="font-black text-[#272343] text-sm italic">{member.name}</p>
                        <p className="text-[10px] text-[#2d334a]/40 font-bold uppercase tracking-widest">
                          {member.paymentsCount} cotisations
                        </p>
                      </div>
                    </div>
                    <div className="w-8 h-8 rounded-lg bg-[#f8fafc] flex items-center justify-center group-hover:bg-[#42c88f]/10 transition-colors">
                      <TrendingUp size={14} className="text-[#42c88f]" />
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, use } from "react";
import { useAuth } from "@/lib/auth-context";
import { 
  Users, Wallet, Link as LinkIcon, Copy, Check, Loader2, ArrowLeft, Plus,
  X, ChevronUp, ChevronDown, GripVertical, XCircle, CheckCircle2, CreditCard
} from "lucide-react";
import Link from "next/link";
import { API_BASE_URL } from "@/lib/api";

import { useToast } from "@/lib/toast";

export default function CircleDetailsPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const { user } = useAuth();
  const { success, error: toastError } = useToast();
  const [circle, setCircle] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [inviteLoading, setInviteLoading] = useState(false);
  const [inviteLink, setInviteLink] = useState("");
  const [inviteToken, setInviteToken] = useState("");
  const [copied, setCopied] = useState(false);
  const [paymentLoading, setPaymentLoading] = useState<string | null>(null);

  // Modal clôture cycle
  const [closeModal, setCloseModal] = useState(false);
  const [beneficiaryId, setBeneficiaryId] = useState("");
  const [closingCycle, setClosingCycle] = useState(false);

  // Gestion ordre de passage
  const [orderMode, setOrderMode] = useState(false);
  const [tempOrder, setTempOrder] = useState<any[]>([]);
  const [savingOrder, setSavingOrder] = useState(false);

  const fetchCircleDetails = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/circles/${id}`, {
        headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
      });
      const data = await response.json();
      if (response.ok) {
        setCircle(data.circle);
        setTempOrder(data.circle.memberships || []);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCircleDetails();
  }, [id]);

  const handleManualPayment = async (memberId: string, cycleId: string, amount: number) => {
    setPaymentLoading(memberId);
    try {
      const response = await fetch(`${API_BASE_URL}/payments`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("token")}`
        },
        body: JSON.stringify({ cycleId, memberId, amount, method: "CASH" })
      });
      if (response.ok) {
        await fetchCircleDetails();
        success("Paiement validé avec succès");
      } else {
        const error = await response.json();
        toastError(error.error || "Erreur lors de la validation");
      }
    } catch (e) {
      console.error(e);
      toastError("Erreur réseau");
    } finally {
      setPaymentLoading(null);
    }
  };

  const generateInvite = async () => {
    setInviteLoading(true);
    try {
      const response = await fetch(`${API_BASE_URL}/circles/${id}/invitations`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("token")}`
        },
        body: JSON.stringify({})
      });
      const data = await response.json();
      if (response.ok) {
        const origin = typeof window !== 'undefined' ? window.location.origin : '';
        setInviteLink(`${origin}/join/${data.invitation.token}`);
        setInviteToken(data.invitation.token);
      }
    } catch (error) {
      console.error("Failed to generate invite", error);
    } finally {
      setInviteLoading(false);
    }
  };

  const revokeInvite = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/invitations/${inviteToken}/revoke`, {
        method: "PATCH",
        headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
      });
      if (response.ok) {
        setInviteLink("");
        setInviteToken("");
        success("Invitation révoquée");
      }
    } catch (error) {
      console.error("Failed to revoke invite", error);
    }
  };

  const handleStartCycle = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/circles/${id}/cycles`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("token")}`
        }
      });
      if (response.ok) {
        success("Cycle démarré avec succès");
        fetchCircleDetails();
      } else {
        const err = await response.json();
        toastError(err.error || "Erreur lors du démarrage du cycle");
      }
    } catch (e) {
      console.error(e);
      toastError("Erreur réseau");
    }
  };

  const handleCloseCycle = async () => {
    if (!beneficiaryId) {
      toastError("Veuillez sélectionner un bénéficiaire");
      return;
    }
    setClosingCycle(true);
    try {
      const response = await fetch(`${API_BASE_URL}/cycles/${activeCycle.id}/close`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("token")}`
        },
        body: JSON.stringify({ beneficiaryId })
      });
      if (response.ok) {
        success("Cycle clôturé avec succès");
        setCloseModal(false);
        setBeneficiaryId("");
        fetchCircleDetails();
      } else {
        const err = await response.json();
        toastError(err.error || "Erreur lors de la clôture");
      }
    } catch (e) {
      console.error(e);
      toastError("Erreur réseau");
    } finally {
      setClosingCycle(false);
    }
  };

  const moveUp = (index: number) => {
    if (index === 0) return;
    const newOrder = [...tempOrder];
    [newOrder[index], newOrder[index - 1]] = [newOrder[index - 1], newOrder[index]];
    setTempOrder(newOrder);
  };

  const moveDown = (index: number) => {
    if (index === tempOrder.length - 1) return;
    const newOrder = [...tempOrder];
    [newOrder[index], newOrder[index + 1]] = [newOrder[index + 1], newOrder[index]];
    setTempOrder(newOrder);
  };

  const saveOrder = async () => {
    setSavingOrder(true);
    try {
      const orders = tempOrder.map((m, idx) => ({
        userId: m.user.id,
        order: idx + 1
      }));
      const response = await fetch(`${API_BASE_URL}/circles/${id}/order`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${localStorage.getItem("token")}`
        },
        body: JSON.stringify({ orders })
      });
      if (response.ok) {
        success("Ordre de passage sauvegardé");
        setOrderMode(false);
        fetchCircleDetails();
      } else {
        const err = await response.json();
        toastError(err.error || "Erreur lors de la sauvegarde");
      }
    } catch (e) {
      console.error(e);
      toastError("Erreur réseau");
    } finally {
      setSavingOrder(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(inviteLink);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (loading) return <div className="flex justify-center p-20"><Loader2 className="animate-spin text-[#ffd803] h-10 w-10" /></div>;
  if (!circle) return <div className="text-center p-20 font-bold text-[#272343]">Cercle non trouvé.</div>;

  const activeCycle = circle.cycles?.find((c: any) => c.status === "OPEN");
  const isOrganizer = user?.id === circle.creator?.id;
  const isOrganizerFallback = user?.id === circle.creatorId;
  const isOrganizerFinal = isOrganizer || isOrganizerFallback;
  const isMember = !isOrganizerFinal && circle.memberships?.some(
    (m: any) => m.user?.id === user?.id || m.userId === user?.id
  );

  // Vérifier si le membre connecté a déjà payé ce cycle
  const myPayment = activeCycle?.payments?.find(
    (p: any) => p.userId === user?.id && (p.status === "CONFIRMED" || p.status === "PENDING")
  );

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <Link href="/dashboard/circles" className="inline-flex items-center gap-2 text-[#2d334a]/60 hover:text-[#272343] font-bold transition-colors group">
        <ArrowLeft className="h-4 w-4 group-hover:-translate-x-1 transition-transform" /> Retour aux cercles
      </Link>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Colonne Gauche */}
        <div className="lg:col-span-2 space-y-6">
          <div className="card-base bg-white overflow-hidden relative ">
            <div className="flex flex-col md:flex-row justify-between gap-6">
              <div>
                <span className="px-3 py-1 bg-[#e3f6f5] text-[#272343] text-[10px] font-bold rounded-full uppercase tracking-widest mb-4 inline-block">
                  {{ WEEKLY: "Hebdomadaire", BIWEEKLY: "Bimensuel", MONTHLY: "Mensuel" }[circle.frequency as string] ?? circle.frequency}
                </span>
                <h1 className="text-3xl font-extrabold mb-2 text-[#272343]">{circle.name}</h1>
                <p className="text-[#2d334a]/60 font-medium mb-6">{circle.description || "Pas de description."}</p>

                <div className="flex flex-wrap gap-4">
                  <div className="flex items-center gap-3 bg-[#f8fafc] px-5 py-3 rounded-2xl border border-[#dfe5f2] shadow-sm">
                    <div className="p-2 bg-[#ffd803]/20 rounded-lg">
                      <Wallet className="h-5 w-5 text-[#272343]" />
                    </div>
                    <div>
                      <p className="text-[10px] uppercase font-bold text-[#2d334a]/40 tracking-wider">Montant</p>
                      <p className="font-extrabold text-[#272343]">{circle.amount.toLocaleString()} FCFA</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-3 bg-[#f8fafc] px-5 py-3 rounded-2xl border border-[#dfe5f2] shadow-sm">
                    <div className="p-2 bg-[#bae8e8]/30 rounded-lg">
                      <Users className="h-5 w-5 text-[#272343]" />
                    </div>
                    <div>
                      <p className="text-[10px] uppercase font-bold text-[#2d334a]/40 tracking-wider">Capacité</p>
                      <p className="font-extrabold text-[#272343]">{circle.memberships?.length || 0} / {circle.maxMembers}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Cycle Actif */}
            {circle.status === "CLOSED" ? (
              <div className="mt-8 p-5 bg-[#f8fafc] border border-[#dfe5f2] rounded-2xl flex items-center gap-3">
                <div className="w-2 h-2 rounded-full bg-[#2d334a]/30 shrink-0" />
                <div>
                  <p className="font-black text-[#272343] text-sm">Tontine terminée</p>
                  <p className="text-xs text-[#2d334a]/60 font-medium mt-0.5">
                    Ce cercle a été clôturé. Tous les membres ont reçu leur tour.
                  </p>
                </div>
              </div>
            ) : activeCycle ? (
              <div className="mt-8 space-y-3">
                <div className="bg-[#fffffe] border-l-4 p-5 rounded-r-2xl shadow-sm border-t border-r border-b border-[#dfe5f2]">
                  <div className="flex justify-between items-center">
                    <div>
                      <h4 className="text-[#272343] font-bold text-sm flex items-center gap-2">
                         <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></div>
                         Cycle Actif #{activeCycle.number}
                      </h4>
                      <p className="text-[11px] text-[#2d334a]/60 font-medium mt-1">
                        Débuté le {new Date(activeCycle.startDate).toLocaleDateString()}
                      </p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="text-right">
                        <p className="text-[10px] uppercase font-bold text-[#2d334a]/40 tracking-wider">Cagnotte</p>
                        <p className="font-extrabold text-[#272343]">{(circle.memberships?.length || 0) * circle.amount} FCFA</p>
                      </div>
                      {isOrganizerFinal && (
                        <button
                          onClick={() => setCloseModal(true)}
                          className="px-4 py-2 bg-[#272343] text-[#ffd803] text-xs font-black rounded-xl hover:bg-[#1a1730] transition-all"
                        >
                          Clôturer
                        </button>
                      )}
                    </div>
                  </div>
                </div>

                {/* Bouton paiement membre */}
                {isMember && (
                  myPayment ? (
                    <div className={`flex items-center gap-3 p-4 rounded-2xl border ${
                      myPayment.status === "CONFIRMED"
                        ? "bg-[#42c88f]/5 border-[#42c88f]/20"
                        : "bg-[#ffd803]/5 border-[#ffd803]/30"
                    }`}>
                      <CheckCircle2 className={`h-5 w-5 shrink-0 ${
                        myPayment.status === "CONFIRMED" ? "text-[#42c88f]" : "text-[#b38a00]"
                      }`} />
                      <p className="text-sm font-black text-[#272343]">
                        {myPayment.status === "CONFIRMED"
                          ? `Cotisation payée ✓ — ${circle.amount.toLocaleString()} FCFA`
                          : "Paiement en cours de validation…"}
                      </p>
                    </div>
                  ) : (
                    <Link
                      href={`/dashboard/member/pay?cycleId=${activeCycle.id}&circleId=${id}`}
                      className="flex items-center justify-center gap-2 w-full py-4 bg-[#ffd803] text-[#272343] font-black rounded-2xl hover:bg-[#e0c700] transition-all shadow-lg shadow-[#ffd803]/20"
                    >
                      <CreditCard className="h-5 w-5" />
                      Payer ma cotisation — {circle.amount.toLocaleString()} FCFA
                    </Link>
                  )
                )}
              </div>
            ) : (
              isOrganizerFinal && (
                <div className="mt-8 space-y-3">
                  <button
                    onClick={handleStartCycle}
                    className="w-full sm:w-auto px-6 py-3 bg-[#ffd803] text-[#272343] font-bold rounded-xl hover:bg-[#ffd803]/80 transition-colors flex items-center justify-center gap-2"
                  >
                    <Check className="h-4 w-4" /> Démarrer un nouveau cycle
                  </button>

                  {/* Fermer le cercle — visible seulement si au moins un cycle a été clôturé */}
                  {circle.cycles?.some((c: any) => c.status === "CLOSED") && (
                    <button
                      onClick={async () => {
                        try {
                          const response = await fetch(`${API_BASE_URL}/circles/${id}`, {
                            method: "PATCH",
                            headers: {
                              "Content-Type": "application/json",
                              "Authorization": `Bearer ${localStorage.getItem("token")}`
                            },
                            body: JSON.stringify({ status: "CLOSED" })
                          });
                          if (response.ok) {
                            success("Cercle fermé. La tontine est terminée.");
                            fetchCircleDetails();
                          } else {
                            const err = await response.json();
                            toastError(err.error || "Erreur");
                          }
                        } catch {
                          toastError("Erreur réseau");
                        }
                      }}
                      className="w-full sm:w-auto px-6 py-3 bg-[#f8fafc] border border-[#dfe5f2] text-[#2d334a]/60 font-bold rounded-xl hover:bg-[#f25f4c]/5 hover:border-[#f25f4c]/20 hover:text-[#f25f4c] transition-all flex items-center justify-center gap-2 text-sm"
                    >
                      Fermer définitivement ce cercle
                    </button>
                  )}
                </div>
              )
            )}
          </div>

          {/* Membres */}
          <div className="card-base">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2 text-[#272343]">
                <Users className="h-5 w-5 text-[#ffd803]" /> Membres ({circle.memberships?.length || 0})
              </h3>
              {isOrganizerFinal && !orderMode && (
                <button
                  onClick={() => { setOrderMode(true); setTempOrder(circle.memberships || []); }}
                  className="text-xs font-black px-4 py-2 bg-[#e3f6f5] text-[#272343] rounded-xl hover:bg-[#bae8e8] transition-all"
                >
                  Définir l'ordre
                </button>
              )}
              {orderMode && (
                <div className="flex gap-2">
                  <button
                    onClick={() => { setOrderMode(false); setTempOrder(circle.memberships || []); }}
                    className="text-xs font-black px-4 py-2 bg-[#f8fafc] border border-[#dfe5f2] text-[#272343] rounded-xl hover:bg-[#e3f6f5] transition-all"
                  >
                    Annuler
                  </button>
                  <button
                    onClick={saveOrder}
                    disabled={savingOrder}
                    className="text-xs font-black px-4 py-2 bg-[#42c88f] text-white rounded-xl hover:bg-[#38b07d] transition-all disabled:opacity-50 flex items-center gap-1"
                  >
                    {savingOrder ? <Loader2 className="h-3 w-3 animate-spin" /> : <CheckCircle2 className="h-3 w-3" />}
                    Sauvegarder
                  </button>
                </div>
              )}
            </div>

            {circle.memberships?.length > 0 ? (
              <div className="grid grid-cols-1 gap-4">
                {(orderMode ? tempOrder : circle.memberships).map((m: any, idx: number) => {
                  const hasPaidThisCycle = activeCycle?.payments?.some((p: any) => p.userId === m.user.id && p.status === "CONFIRMED");

                  return (
                    <div key={m.id} className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-4 bg-[#f8fafc] rounded-2xl border border-[#dfe5f2] hover:border-[#bae8e8] transition-colors gap-4">
                      <div className="flex items-center gap-3 flex-1">
                        {orderMode && (
                          <div className="flex flex-col gap-1">
                            <button onClick={() => moveUp(idx)} disabled={idx === 0} className="p-1 hover:bg-[#e3f6f5] rounded disabled:opacity-30">
                              <ChevronUp className="h-3 w-3 text-[#272343]" />
                            </button>
                            <GripVertical className="h-4 w-4 text-[#2d334a]/40" />
                            <button onClick={() => moveDown(idx)} disabled={idx === tempOrder.length - 1} className="p-1 hover:bg-[#e3f6f5] rounded disabled:opacity-30">
                              <ChevronDown className="h-3 w-3 text-[#272343]" />
                            </button>
                          </div>
                        )}
                        <div className="w-10 h-10 bg-[#bae8e8] rounded-full flex items-center justify-center font-bold text-sm text-[#272343] border-2 border-white shadow-sm shrink-0">
                          {orderMode ? idx + 1 : (m.order || idx + 1)}
                        </div>
                        <div>
                          <p className="font-bold text-sm text-[#272343]">{m.user.name}</p>
                          <p className="text-[10px] text-[#2d334a]/40 font-bold uppercase">{m.role}</p>
                        </div>
                      </div>

                      {!orderMode && (
                        <div className="flex items-center gap-2 w-full sm:w-auto justify-between sm:justify-end">
                          {m.user.id === circle.creator.id && (
                            <span className="px-2 py-1 bg-[#ffd803]/10 text-[#272343] text-[9px] font-bold rounded-md">ORG</span>
                          )}

                          {activeCycle && isOrganizerFinal && m.user.id !== user?.id && (
                            hasPaidThisCycle ? (
                              <span className="flex items-center gap-1 text-[10px] font-bold text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-lg border border-emerald-100">
                                <Check className="h-3 w-3" /> Payé
                              </span>
                            ) : (
                              <button 
                                onClick={() => handleManualPayment(m.user.id, activeCycle.id, circle.amount)}
                                disabled={paymentLoading === m.user.id}
                                className="text-[10px] font-bold bg-[#bae8e8] hover:bg-[#bae8e8]/80 text-[#272343] px-3 py-1.5 rounded-lg transition-colors flex items-center gap-1 disabled:opacity-50"
                              >
                                {paymentLoading === m.user.id ? <Loader2 className="h-3 w-3 animate-spin"/> : <Wallet className="h-3 w-3" />}
                                Valider
                              </button>
                            )
                          )}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="text-center py-16 bg-[#f8fafc] rounded-[32px] border-2 border-dashed border-[#dfe5f2]">
                <Users className="h-10 w-10 text-[#2d334a]/20 mx-auto mb-4" />
                <p className="text-[#2d334a]/40 font-bold mb-6">Aucun membre pour le moment.</p>
              </div>
            )}
          </div>
        </div>

        {/* Colonne Droite */}
        <div className="space-y-6">
          <div className="card-base bg-[#272343] text-white border-none shadow-[0_20px_50px_rgba(39,35,67,0.15)] relative overflow-hidden">
            <div className="relative z-10">
              <h3 className="text-lg font-bold mb-3 flex items-center gap-2">
                <LinkIcon className="h-5 w-5 text-[#ffd803]" /> Recrutement
              </h3>
              <p className="text-white/60 text-sm mb-6 font-medium leading-relaxed">
                Partagez ce lien sécurisé pour recruter des membres.
              </p>

              {inviteLink ? (
                <div className="space-y-4">
                  <div className="relative">
                    <input 
                      readOnly 
                      value={inviteLink}
                      className="w-full bg-white/10 border border-white/20 rounded-xl px-4 py-4 text-xs font-mono text-white/90 focus:outline-none"
                    />
                    <button 
                      onClick={copyToClipboard}
                      className="absolute right-2 top-2 p-2 bg-[#ffd803] text-[#272343] rounded-lg hover:scale-105 active:scale-95 transition-all shadow-lg"
                    >
                      {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
                    </button>
                  </div>
                  {copied && <p className="text-[10px] text-[#ffd803] font-bold text-center animate-pulse">Copié !</p>}
                  <button
                    onClick={revokeInvite}
                    className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-[#f25f4c] text-white text-xs font-black rounded-xl hover:bg-[#d94f3d] transition-all"
                  >
                    <XCircle className="h-4 w-4" />
                    Révoquer cette invitation
                  </button>
                </div>
              ) : (
                <button 
                  onClick={generateInvite} 
                  disabled={inviteLoading} 
                  className="btn-primary w-full flex items-center justify-center gap-2 py-4 shadow-xl"
                >
                  {inviteLoading ? <Loader2 className="animate-spin h-5 w-5" /> : <Plus className="h-5 w-5" />}
                  Générer le lien
                </button>
              )}
            </div>
            <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-white/5 rounded-full blur-2xl"></div>
          </div>

          <div className="bg-[#e3f6f5] p-8 rounded-[32px] border border-[#bae8e8]">
            <h4 className="font-bold text-sm mb-4 text-[#272343]">Statistiques</h4>
            <div className="space-y-4">
              <div className="flex justify-between items-center text-xs">
                <span className="text-[#2d334a]/60">Places restantes</span>
                <span className="font-extrabold text-[#272343]">{circle.maxMembers - (circle.memberships?.length || 0)}</span>
              </div>
              <div className="w-full bg-white/50 h-2 rounded-full overflow-hidden">
                <div 
                  className="bg-[#ffd803] h-full transition-all duration-1000" 
                  style={{ width: `${((circle.memberships?.length || 0) / circle.maxMembers) * 100}%` }}
                ></div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Modal Clôture Cycle */}
      {closeModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[32px] p-8 w-full max-w-md shadow-2xl animate-in fade-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-[#272343]">Clôturer le cycle #{activeCycle?.number}</h3>
              <button onClick={() => setCloseModal(false)} className="p-2 hover:bg-[#f8fafc] rounded-xl transition-all">
                <X className="h-5 w-5 text-[#2d334a]/60" />
              </button>
            </div>
            <p className="text-sm text-[#2d334a]/60 font-medium mb-6">
              Sélectionnez le membre qui recevra la cagnotte de ce cycle.
            </p>
            <select
              value={beneficiaryId}
              onChange={(e) => setBeneficiaryId(e.target.value)}
              className="input-base mb-6"
            >
              <option value="">-- Choisir un bénéficiaire --</option>
              {circle.memberships?.map((m: any) => (
                <option key={m.user.id} value={m.user.id}>
                  {m.user.name} {m.order ? `(#${m.order})` : ""}
                </option>
              ))}
            </select>
            <div className="flex gap-3">
              <button
                onClick={() => setCloseModal(false)}
                className="flex-1 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-black text-[#272343] hover:bg-[#e3f6f5] transition-all"
              >
                Annuler
              </button>
              <button
                onClick={handleCloseCycle}
                disabled={closingCycle || !beneficiaryId}
                className="flex-1 py-3 bg-[#272343] text-[#ffd803] rounded-xl font-black transition-all disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {closingCycle ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                Confirmer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { ArrowLeft, Diamond, Calendar, Users, Info, Loader2, AlertCircle } from "lucide-react";
import Link from "next/link";
import { fetchApi } from "@/lib/api";

interface FormErrors {
  name?: string;
  amount?: string;
  maxMembers?: string;
}

// ── Défini EN DEHORS du composant pour éviter le re-mount à chaque frappe ──
function Field({
  label,
  error,
  children,
}: {
  label: string;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-2">
      <label className="text-xs font-black uppercase tracking-widest text-[#2d334a]/60">
        {label}
      </label>
      {children}
      {error && (
        <p className="flex items-center gap-1.5 text-xs text-[#f25f4c] font-bold">
          <AlertCircle className="h-3.5 w-3.5 shrink-0" />
          {error}
        </p>
      )}
    </div>
  );
}

export default function NewCirclePage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [serverError, setServerError] = useState("");
  const [errors, setErrors] = useState<FormErrors>({});

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [frequency, setFrequency] = useState("MONTHLY");
  const [maxMembers, setMaxMembers] = useState("");

  const clearError = (field: keyof FormErrors) =>
    setErrors((prev) => ({ ...prev, [field]: undefined }));

  const validate = (): boolean => {
    const e: FormErrors = {};

    if (!name.trim()) {
      e.name = "Le nom du cercle est requis";
    } else if (name.trim().length < 3) {
      e.name = "Le nom doit faire au moins 3 caractères";
    }

    if (!amount) {
      e.amount = "Le montant de la cotisation est requis";
    } else if (isNaN(Number(amount)) || Number(amount) <= 0) {
      e.amount = "Le montant doit être un nombre positif";
    } else if (Number(amount) < 100) {
      e.amount = "Le montant minimum est de 100 FCFA";
    }

    if (!maxMembers) {
      e.maxMembers = "Le nombre de membres est requis";
    } else if (isNaN(Number(maxMembers)) || Number(maxMembers) < 2) {
      e.maxMembers = "Il faut au moins 2 membres";
    } else if (Number(maxMembers) > 50) {
      e.maxMembers = "Maximum 50 membres par cercle";
    }

    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setServerError("");
    if (!validate()) return;

    setLoading(true);
    try {
      const data = await fetchApi("/circles", {
        method: "POST",
        body: JSON.stringify({
          name: name.trim(),
          description: description.trim() || undefined,
          amount: Number(amount),
          frequency,
          maxMembers: Number(maxMembers),
        }),
      });
      router.push(`/dashboard/circles/${data.circle.id}`);
    } catch (error: any) {
      // Erreur KYC — rediriger vers le profil
      if (error.message?.includes("KYC")) {
        setServerError(error.message + " → Allez dans votre profil pour soumettre votre KYC.");
      } else {
        setServerError(error.message);
      }
    } finally {
      setLoading(false);
    }
  };

  const inputClass = (hasError?: string) =>
    `input-base ${hasError ? "border-[#f25f4c] focus:ring-[#f25f4c]" : ""}`;

  return (
    <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div>
        <Link
          href="/dashboard"
          className="inline-flex items-center gap-2 text-[#2d334a]/40 hover:text-[#272343] mb-4 text-sm font-bold transition-colors group"
        >
          <ArrowLeft className="h-4 w-4 group-hover:-translate-x-1 transition-transform" />
          Dashboard
        </Link>
        <h1 className="text-3xl font-black text-[#272343] tracking-tight">
          Nouveau <span className="text-[#ffd803]">Cercle</span>
        </h1>
        <p className="text-sm text-[#2d334a]/40 font-medium mt-0.5">
          Définissez les règles de votre tontine.
        </p>
      </div>

      <form onSubmit={handleSubmit} noValidate className="card-base space-y-8">

        {serverError && (
          <div className="flex items-center gap-3 p-4 bg-[#f25f4c]/10 border border-[#f25f4c]/20 rounded-2xl">
            <AlertCircle className="h-5 w-5 text-[#f25f4c] shrink-0" />
            <p className="text-sm text-[#f25f4c] font-bold">{serverError}</p>
          </div>
        )}

        {/* Section 1 — Identité */}
        <div className="space-y-5">
          <h2 className="text-xs font-black uppercase tracking-widest text-[#ffd803]">
            1. Identité du cercle
          </h2>

          <Field label="Nom du cercle *" error={errors.name}>
            <input
              type="text"
              placeholder="Ex: Tontine des Entrepreneurs"
              className={inputClass(errors.name)}
              value={name}
              onChange={(e) => { setName(e.target.value); clearError("name"); }}
            />
          </Field>

          <Field label="Description (optionnel)">
            <textarea
              placeholder="Expliquez l'objectif de ce cercle…"
              className="input-base h-24 resize-none"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </Field>
        </div>

        {/* Section 2 — Financier */}
        <div className="space-y-5">
          <h2 className="text-xs font-black uppercase tracking-widest text-[#ffd803]">
            2. Configuration financière
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
            <Field label="Montant de la cotisation (FCFA) *" error={errors.amount}>
              <div className="relative">
                <Diamond className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-[#2d334a]/30" />
                <input
                  type="number"
                  placeholder="Ex: 25000"
                  min="100"
                  className={`${inputClass(errors.amount)} pl-11`}
                  value={amount}
                  onChange={(e) => { setAmount(e.target.value); clearError("amount"); }}
                />
              </div>
            </Field>

            <Field label="Fréquence des tours">
              <div className="relative">
                <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-[#2d334a]/30" />
                <select
                  className="input-base pl-11 appearance-none"
                  value={frequency}
                  onChange={(e) => setFrequency(e.target.value)}
                >
                  <option value="WEEKLY">Hebdomadaire</option>
                  <option value="BIWEEKLY">Bimensuelle</option>
                  <option value="MONTHLY">Mensuelle</option>
                </select>
              </div>
            </Field>
          </div>
        </div>

        {/* Section 3 — Membres */}
        <div className="space-y-5">
          <h2 className="text-xs font-black uppercase tracking-widest text-[#ffd803]">
            3. Membres
          </h2>

          <Field label="Nombre maximum de membres *" error={errors.maxMembers}>
            <div className="relative">
              <Users className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-[#2d334a]/30" />
              <input
                type="number"
                placeholder="Ex: 10"
                min="2"
                max="50"
                className={`${inputClass(errors.maxMembers)} pl-11`}
                value={maxMembers}
                onChange={(e) => { setMaxMembers(e.target.value); clearError("maxMembers"); }}
              />
            </div>
          </Field>
        </div>

        {/* Footer */}
        <div className="pt-4 border-t border-[#dfe5f2] flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div className="flex items-start gap-2 text-xs text-[#2d334a]/40 font-medium">
            <Info className="h-4 w-4 shrink-0 mt-0.5" />
            <p>Une fois créé, certains paramètres ne pourront plus être modifiés.</p>
          </div>
          <button
            type="submit"
            disabled={loading}
            className="btn-primary flex items-center gap-2 px-8 py-4 disabled:opacity-50 shrink-0"
          >
            {loading ? <Loader2 className="h-5 w-5 animate-spin" /> : null}
            {loading ? "Création…" : "Créer le cercle"}
          </button>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { fetchApi } from "@/lib/api";
import {
  Plus,
  LayoutGrid,
  List,
  ArrowLeft,
  Loader2,
  Search,
  Users,
  Wallet,
  ArrowUpRight,
  X,
} from "lucide-react";
import Link from "next/link";

type ViewMode = "grid" | "list";
type StatusFilter = "ALL" | "ACTIVE" | "PENDING" | "CLOSED";

const FREQ_LABELS: Record<string, string> = {
  WEEKLY: "Hebdo",
  BIWEEKLY: "Bimensuel",
  MONTHLY: "Mensuel",
};

const STATUS_CONFIG: Record<string, { label: string; color: string }> = {
  ACTIVE:  { label: "En cours",  color: "bg-[#42c88f]/10 text-[#42c88f]" },
  PENDING: { label: "En cours",  color: "bg-[#42c88f]/10 text-[#42c88f]" }, // legacy
  CLOSED:  { label: "Terminé",   color: "bg-[#dfe5f2] text-[#2d334a]/60" },
};

export default function MyCirclesPage() {
  const [circles, setCircles] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("ALL");
  const [viewMode, setViewMode] = useState<ViewMode>("grid");

  useEffect(() => {
    fetchApi("/circles")
      .then((data) => setCircles(data.circles || []))
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  // Filtrage combiné : recherche + statut
  const filtered = useMemo(() => {
    return circles.filter((c) => {
      const matchSearch =
        search.trim() === "" ||
        c.name.toLowerCase().includes(search.toLowerCase()) ||
        (c.description ?? "").toLowerCase().includes(search.toLowerCase());

      const matchStatus =
        statusFilter === "ALL" || c.status === statusFilter;

      return matchSearch && matchStatus;
    });
  }, [circles, search, statusFilter]);

  const statusFilters: { label: string; value: StatusFilter }[] = [
    { label: "Tous", value: "ALL" },
    { label: "Actifs", value: "ACTIVE" },
    { label: "En attente", value: "PENDING" },
    { label: "Clôturés", value: "CLOSED" },
  ];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <Link
            href="/dashboard"
            className="inline-flex items-center gap-2 text-[#2d334a]/40 hover:text-[#272343] mb-3 text-sm font-bold transition-colors group"
          >
            <ArrowLeft className="h-4 w-4 group-hover:-translate-x-1 transition-transform" />
            Dashboard
          </Link>
          <h1 className="text-3xl font-black text-[#272343] tracking-tight">
            Mes <span className="text-[#ffd803]">Cercles</span>
          </h1>
          <p className="text-sm text-[#2d334a]/40 font-medium mt-0.5">
            {circles.length} cercle{circles.length !== 1 ? "s" : ""} au total
          </p>
        </div>
        <Link
          href="/dashboard/circles/new"
          className="btn-primary flex items-center gap-2 px-6 py-3 shadow-sm hover:-translate-y-0.5 transition-all"
        >
          <Plus className="h-5 w-5" /> Nouveau cercle
        </Link>
      </div>

      {/* Barre de recherche + filtres + toggle vue */}
      <div className="flex flex-col gap-3">
        {/* Ligne 1 : recherche + toggle */}
        <div className="flex items-center gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-[#2d334a]/30" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Rechercher un cercle…"
              className="w-full h-11 pl-11 pr-10 bg-white border border-[#dfe5f2] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#ffd803] transition-all placeholder:text-[#2d334a]/30"
            />
            {search && (
              <button
                onClick={() => setSearch("")}
                className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-[#2d334a]/30 hover:text-[#272343] transition-colors"
              >
                <X className="h-4 w-4" />
              </button>
            )}
          </div>

          {/* Toggle grid / liste */}
          <div className="flex items-center bg-[#f8fafc] border border-[#dfe5f2] rounded-xl p-1 gap-1 shrink-0">
            <button
              onClick={() => setViewMode("grid")}
              className={`p-2 rounded-lg transition-all ${
                viewMode === "grid"
                  ? "bg-white shadow-sm text-[#272343]"
                  : "text-[#2d334a]/30 hover:text-[#272343]"
              }`}
              title="Vue grille"
            >
              <LayoutGrid className="h-4 w-4" />
            </button>
            <button
              onClick={() => setViewMode("list")}
              className={`p-2 rounded-lg transition-all ${
                viewMode === "list"
                  ? "bg-white shadow-sm text-[#272343]"
                  : "text-[#2d334a]/30 hover:text-[#272343]"
              }`}
              title="Vue liste"
            >
              <List className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Ligne 2 : filtres statut */}
        <div className="flex items-center gap-2 flex-wrap">
          {statusFilters.map((f) => (
            <button
              key={f.value}
              onClick={() => setStatusFilter(f.value)}
              className={`px-3 py-1.5 rounded-xl text-xs font-black transition-all ${
                statusFilter === f.value
                  ? "bg-[#272343] text-[#ffd803]"
                  : "bg-[#f8fafc] text-[#2d334a]/60 border border-[#dfe5f2] hover:border-[#272343]"
              }`}
            >
              {f.label}
              {f.value !== "ALL" && (
                <span className="ml-1.5 opacity-60">
                  {circles.filter((c) => c.status === f.value).length}
                </span>
              )}
            </button>
          ))}

          {/* Résultat de la recherche */}
          {(search || statusFilter !== "ALL") && (
            <span className="text-xs text-[#2d334a]/40 font-medium ml-1">
              {filtered.length} résultat{filtered.length !== 1 ? "s" : ""}
            </span>
          )}
        </div>
      </div>

      {/* Contenu */}
      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 gap-4">
          <Loader2 className="h-8 w-8 animate-spin text-[#ffd803]" />
          <p className="text-sm text-[#2d334a]/40 font-medium">Chargement…</p>
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-20 border-2 border-dashed border-[#dfe5f2] rounded-[32px]">
          <Users className="h-10 w-10 text-[#2d334a]/20 mx-auto mb-4" />
          <p className="font-black text-[#272343]">
            {search || statusFilter !== "ALL"
              ? "Aucun cercle ne correspond à votre recherche"
              : "Aucun cercle pour le moment"}
          </p>
          <p className="text-sm text-[#2d334a]/40 font-medium mt-1 mb-6">
            {search || statusFilter !== "ALL"
              ? "Essayez de modifier vos filtres."
              : "Créez votre premier cercle pour commencer."}
          </p>
          {!search && statusFilter === "ALL" && (
            <Link href="/dashboard/circles/new" className="btn-primary px-6 inline-flex items-center gap-2">
              <Plus className="h-4 w-4" /> Créer un cercle
            </Link>
          )}
        </div>
      ) : viewMode === "grid" ? (
        /* ── Vue Grille ── */
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {filtered.map((circle) => {
            const statusCfg = STATUS_CONFIG[circle.status] ?? STATUS_CONFIG.PENDING;
            return (
              <Link
                key={circle.id}
                href={`/dashboard/circles/${circle.id}`}
                className="card-base group hover:border-[#ffd803] transition-all flex flex-col"
              >
                <div className="flex items-start justify-between mb-4">
                  <span className={`text-[9px] font-black px-2 py-1 rounded-lg ${statusCfg.color}`}>
                    {statusCfg.label}
                  </span>
                  <ArrowUpRight className="h-4 w-4 text-[#2d334a]/20 group-hover:text-[#ffd803] transition-all" />
                </div>

                <h3 className="font-black text-[#272343] text-lg leading-tight mb-1">
                  {circle.name}
                </h3>
                <p className="text-sm text-[#2d334a]/50 font-medium line-clamp-2 mb-4 flex-1">
                  {circle.description || "Aucune description."}
                </p>

                <div className="pt-4 border-t border-[#dfe5f2] grid grid-cols-3 gap-2">
                  <div>
                    <p className="text-[9px] uppercase font-black tracking-widest text-[#2d334a]/30">
                      Cotisation
                    </p>
                    <p className="text-sm font-black text-[#272343] mt-0.5">
                      {circle.amount.toLocaleString("fr-FR")}
                      <span className="text-[9px] font-normal ml-0.5">FCFA</span>
                    </p>
                  </div>
                  <div>
                    <p className="text-[9px] uppercase font-black tracking-widest text-[#2d334a]/30">
                      Fréquence
                    </p>
                    <p className="text-sm font-black text-[#272343] mt-0.5">
                      {FREQ_LABELS[circle.frequency] ?? circle.frequency}
                    </p>
                  </div>
                  <div>
                    <p className="text-[9px] uppercase font-black tracking-widest text-[#2d334a]/30">
                      Membres
                    </p>
                    <p className="text-sm font-black text-[#272343] mt-0.5">
                      {circle.memberships?.length ?? 0}/{circle.maxMembers}
                    </p>
                  </div>
                </div>
              </Link>
            );
          })}
        </div>
      ) : (
        /* ── Vue Liste ── */
        <div className="divide-y divide-[#dfe5f2] border border-[#dfe5f2] rounded-2xl overflow-hidden bg-white">
          {filtered.map((circle) => {
            const statusCfg = STATUS_CONFIG[circle.status] ?? STATUS_CONFIG.PENDING;
            return (
              <Link
                key={circle.id}
                href={`/dashboard/circles/${circle.id}`}
                className="flex items-center gap-4 px-5 py-4 hover:bg-[#f8fafc] transition-colors group"
              >
                {/* Icône */}
                <div className="w-10 h-10 bg-[#e3f6f5] rounded-xl flex items-center justify-center shrink-0 group-hover:bg-[#ffd803]/10 transition-colors">
                  <Users className="h-5 w-5 text-[#272343]" />
                </div>

                {/* Nom + description */}
                <div className="flex-1 min-w-0">
                  <p className="font-black text-[#272343] text-sm truncate">{circle.name}</p>
                  <p className="text-xs text-[#2d334a]/40 font-medium truncate">
                    {circle.description || "Aucune description"}
                  </p>
                </div>

                {/* Infos */}
                <div className="hidden md:flex items-center gap-6 shrink-0">
                  <div className="text-right">
                    <p className="text-[9px] uppercase font-black tracking-widest text-[#2d334a]/30">
                      Cotisation
                    </p>
                    <p className="text-sm font-black text-[#272343]">
                      {circle.amount.toLocaleString("fr-FR")} FCFA
                    </p>
                  </div>
                  <div className="text-right">
                    <p className="text-[9px] uppercase font-black tracking-widest text-[#2d334a]/30">
                      Membres
                    </p>
                    <p className="text-sm font-black text-[#272343]">
                      {circle.memberships?.length ?? 0}/{circle.maxMembers}
                    </p>
                  </div>
                  <span className={`text-[9px] font-black px-2 py-1 rounded-lg ${statusCfg.color}`}>
                    {statusCfg.label}
                  </span>
                </div>

                <ArrowUpRight className="h-4 w-4 text-[#2d334a]/20 group-hover:text-[#ffd803] transition-all shrink-0" />
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { fetchApi } from "@/lib/api";
import { useAuth } from "@/lib/auth-context";
import {
  AlertTriangle, Plus, X, Loader2, RefreshCw, Clock, CheckCircle2, Search,
} from "lucide-react";

interface Dispute {
  id: string;
  subject: string;
  description: string;
  status: "OPEN" | "IN_REVIEW" | "RESOLVED" | "CLOSED";
  resolution: string | null;
  createdAt: string;
  circle: { id: string; name: string };
}

interface Circle { id: string; name: string }

const STATUS_CONFIG = {
  OPEN:      { label: "Ouvert",      color: "bg-[#f25f4c]/10 text-[#f25f4c]",   icon: AlertTriangle },
  IN_REVIEW: { label: "En cours",    color: "bg-[#ffd803]/10 text-[#b38a00]",   icon: Clock },
  RESOLVED:  { label: "Résolu",      color: "bg-[#42c88f]/10 text-[#42c88f]",   icon: CheckCircle2 },
  CLOSED:    { label: "Clôturé",     color: "bg-[#dfe5f2] text-[#2d334a]/60",   icon: CheckCircle2 },
};

export default function DisputesPage() {
  const { user } = useAuth();
  const [disputes, setDisputes] = useState<Dispute[]>([]);
  const [circles, setCircles] = useState<Circle[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [formError, setFormError] = useState<string | null>(null);

  const [form, setForm] = useState({ circleId: "", subject: "", description: "" });

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [disputesData, circlesData] = await Promise.all([
        fetchApi("/disputes/me"),
        fetchApi("/circles/joined"),
      ]);
      setDisputes(disputesData.disputes);
      setCircles(circlesData.circles || []);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);
    if (!form.circleId) { setFormError("Sélectionnez un cercle"); return; }
    if (!form.subject.trim()) { setFormError("Le sujet est requis"); return; }
    if (form.description.trim().length < 20) { setFormError("La description doit faire au moins 20 caractères"); return; }

    setSubmitting(true);
    try {
      await fetchApi("/disputes", {
        method: "POST",
        body: JSON.stringify(form),
      });
      setShowForm(false);
      setForm({ circleId: "", subject: "", description: "" });
      fetchData();
    } catch (e: any) {
      setFormError(e.message);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-[#272343] tracking-tight">
            Mes <span className="text-[#ffd803]">Litiges</span>
          </h1>
          <p className="text-sm text-[#2d334a]/40 font-medium mt-0.5">
            Signalez un problème dans un cercle.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={fetchData} disabled={loading} className="p-2 text-[#2d334a]/40 hover:text-[#272343] hover:bg-[#f8fafc] rounded-xl transition-all">
            <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          </button>
          <button
            onClick={() => setShowForm(true)}
            className="btn-primary flex items-center gap-2 px-4 py-2 text-sm"
          >
            <Plus className="h-4 w-4" /> Signaler
          </button>
        </div>
      </div>

      {error && <p className="text-sm text-[#f25f4c] font-bold">{error}</p>}

      {/* Liste */}
      {loading ? (
        <div className="flex justify-center py-16"><Loader2 className="h-8 w-8 animate-spin text-[#ffd803]" /></div>
      ) : disputes.length === 0 ? (
        <div className="text-center py-20 border-2 border-dashed border-[#dfe5f2] rounded-[32px]">
          <AlertTriangle className="h-10 w-10 text-[#2d334a]/20 mx-auto mb-3" />
          <p className="font-black text-[#272343]">Aucun litige</p>
          <p className="text-sm text-[#2d334a]/40 font-medium mt-1">
            Vous n'avez signalé aucun problème pour le moment.
          </p>
        </div>
      ) : (
        <div className="divide-y divide-[#dfe5f2] border border-[#dfe5f2] rounded-2xl overflow-hidden bg-white">
          {disputes.map((d) => {
            const cfg = STATUS_CONFIG[d.status];
            const Icon = cfg.icon;
            return (
              <div key={d.id} className="p-5 hover:bg-[#f8fafc] transition-colors">
                <div className="flex items-start justify-between gap-4 mb-2">
                  <p className="font-black text-[#272343] text-sm">{d.subject}</p>
                  <span className={`flex items-center gap-1 text-[9px] font-black px-2 py-1 rounded-lg shrink-0 ${cfg.color}`}>
                    <Icon className="h-3 w-3" />
                    {cfg.label}
                  </span>
                </div>
                <p className="text-xs text-[#2d334a]/60 font-medium line-clamp-2 mb-2">{d.description}</p>
                <div className="flex items-center justify-between">
                  <span className="text-[10px] text-[#2d334a]/40 font-bold uppercase tracking-widest">
                    {d.circle.name}
                  </span>
                  <span className="text-[10px] text-[#2d334a]/40 font-medium">
                    {new Date(d.createdAt).toLocaleDateString("fr-FR")}
                  </span>
                </div>
                {d.resolution && (
                  <div className="mt-3 p-3 bg-[#42c88f]/5 border border-[#42c88f]/20 rounded-xl">
                    <p className="text-xs font-black text-[#42c88f] mb-1">Résolution</p>
                    <p className="text-xs text-[#272343] font-medium">{d.resolution}</p>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Modal formulaire */}
      {showForm && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[32px] p-8 w-full max-w-md shadow-2xl animate-in fade-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-black text-[#272343]">Signaler un litige</h3>
              <button onClick={() => setShowForm(false)} className="p-2 hover:bg-[#f8fafc] rounded-xl transition-all">
                <X className="h-5 w-5 text-[#2d334a]/60" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-[#2d334a]/40">Cercle concerné *</label>
                <select
                  value={form.circleId}
                  onChange={(e) => setForm({ ...form, circleId: e.target.value })}
                  className="input-base"
                >
                  <option value="">-- Sélectionner un cercle --</option>
                  {circles.map((c) => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-[#2d334a]/40">Sujet *</label>
                <input
                  type="text"
                  value={form.subject}
                  onChange={(e) => setForm({ ...form, subject: e.target.value })}
                  placeholder="Ex: Paiement non enregistré"
                  className="input-base"
                />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black uppercase tracking-widest text-[#2d334a]/40">Description *</label>
                <textarea
                  value={form.description}
                  onChange={(e) => setForm({ ...form, description: e.target.value })}
                  placeholder="Décrivez le problème en détail (min. 20 caractères)…"
                  rows={4}
                  className="input-base resize-none"
                />
                <p className="text-[10px] text-[#2d334a]/40 font-medium text-right">
                  {form.description.length} / 20 min
                </p>
              </div>

              {formError && (
                <p className="text-sm text-[#f25f4c] font-bold flex items-center gap-1.5">
                  <AlertTriangle className="h-4 w-4" />{formError}
                </p>
              )}

              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setShowForm(false)}
                  className="flex-1 py-3 bg-[#f8fafc] border border-[#dfe5f2] rounded-xl font-black text-[#272343] hover:bg-[#e3f6f5] transition-all">
                  Annuler
                </button>
                <button type="submit" disabled={submitting}
                  className="flex-1 py-3 bg-[#272343] text-[#ffd803] rounded-xl font-black transition-all disabled:opacity-50 flex items-center justify-center gap-2">
                  {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <AlertTriangle className="h-4 w-4" />}
                  Signaler
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

