      </div>

      {/* Prochain cycle à payer */}
      {nextCycle && (
        <div className="card-base bg-[#272343] border-none text-white flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
