              <p className="text-sm text-white/60 font-medium">
                Cycle #{nextCycle.number} · échéance{" "}
                {nextCycle.endDate
                  ? new Date(nextCycle.endDate).toLocaleDateString("fr-FR", {
                      day: "2-digit",
                      month: "long",
                    })
                  : "—"}
              </p>
            </div>
          </div>
          <Link
